test(
  'the equivalent zoom layout keeps both board sizes playable',
  async ({ page }) => {
    await loadFixedBoard(page);
    await expect
      .poll(() => page.evaluate(() => ({ width: innerWidth, ratio: devicePixelRatio })))
      .toEqual({ width: 640, ratio: 2 });
    await finishBoard(page);
    const readable = await page.locator('.controls, .stats, .victory').evaluateAll((elements) => {
      const boxes = elements.map((element) => element.getBoundingClientRect());
      return boxes.every(
        (box, index) =>
          box.width > 0 &&
          box.height > 0 &&
          box.left >= 0 &&
          box.right <= innerWidth &&
          (!index || box.top >= (boxes[index - 1]?.bottom ?? 0)),
      );
    });
    expect(readable).toBe(true);
    await expectReadableText(page);
    const completed = await exportedSnapshot(page);
    await page.locator('summary').click();
    await page
      .getByLabel(ReproductionControl.snapshot, { exact: true })
      .fill(JSON.stringify(completed));
    await page.getByRole('button', { name: ReproductionControl.loadSnapshot, exact: true }).click();
    await expect(
      page.getByRole('button', { name: ReproductionControl.resume, exact: true }),
    ).toHaveCount(0);
    await expectReadableText(page);
    await page.getByLabel(ReproductionControl.snapshot, { exact: true }).fill(
      JSON.stringify({
        ...completed,
        matched: [],
        moves: 0,
        selection: { kind: 'one', index: 0 },
      }),
    );
    await page.getByRole('button', { name: ReproductionControl.loadSnapshot, exact: true }).click();
    await expect(
      page.getByRole('button', { name: ReproductionControl.resume, exact: true }),
    ).toBeVisible();
    await expectReadableText(page);
    await page.getByRole('button', { name: ReproductionControl.resume, exact: true }).click();
    await page.locator('summary').click();
    await page.getByRole('button', { name: DealControl.restart, exact: true }).click();
    await page.locator('.card').first().focus();
    await page.keyboard.press('Space');
    await expect(page.locator('.card.revealed')).toHaveCount(1);
    await page.getByLabel(DealControl.size, { exact: true }).selectOption('16');
    await expect(page.locator('.card')).toHaveCount(256);
    await page.locator('.card').first().click();
    await page.locator('.card').first().focus();
    await expectFocusInside(page.locator('.card').first());
    await moveKeyboardTo(page, 16 ** 2 - 1, 16);
    await expect(page.locator('.card').last()).toBeFocused();
    await expectFocusInside(page.locator('.card').last());
    await page.keyboard.press('Enter');
    await expect(page.locator('.card.revealed, .card.matched')).toHaveCount(2);
    const layout = await page.evaluate(() => ({
      page: document.documentElement.scrollWidth,
      width: innerWidth,
    }));
    expect(layout.page).toBeLessThanOrEqual(layout.width);
  },
  { viewport: { width: 640, height: 400 }, deviceScaleFactor: 2 },
  Scrollbars.hidden,
  TestTimeouts.long,
);
import { expect, test } from './browser-test.ts';
import { ReproductionControl } from '../src/game/controls/control-labels.ts';
import { GRID_SIZES, boardCode } from '../src/game/deck.ts';
import { loadFixedBoard } from './game-fixture.ts';

const SEED = 1;
const LARGEST = GRID_SIZES[GRID_SIZES.length - 1] ?? 0;

// The unit tests finish every size. The browser only shows that the largest board starts and takes a reveal.
test(`a ${LARGEST} by ${LARGEST} game starts with every card ready to reveal`, async ({ page }) => {
  await loadFixedBoard(page);
  await page.locator('summary').click();
  await page.getByLabel(ReproductionControl.board, { exact: true }).fill(boardCode(LARGEST, SEED));
  await page.getByRole('button', { name: ReproductionControl.loadBoard, exact: true }).click();
  await page.locator('summary').click();
  const cards = page.locator('.card');
  await expect(cards).toHaveCount(LARGEST ** 2);
  await expect(page.locator('.card .card-back')).toHaveCount(LARGEST ** 2);
  await cards.first().focus();
  await page.keyboard.press('Enter');
  await expect(cards.first().locator('.card-back')).toHaveCount(0);
  await expect(page.locator('.card .card-back')).toHaveCount(LARGEST ** 2 - 1);
});

import { useCallback, useRef, useState } from 'react';
import { useNearestScroll } from './nearest-scroll.ts';

const KEYBOARD_FOCUS = ':focus-visible';

// Keeps the board's remembered tab stop and scrolls keyboard focus into view with nearest
// alignment.
export function useBoardFocus() {
  const viewport = useRef<HTMLDivElement>(null);
  const element = useRef<HTMLDivElement>(null);
  const [focused, setFocused] = useState(0);
  const scrollToNearest = useNearestScroll(viewport);
  // Focus calls skip the browser's centering scroll and then scroll with nearest alignment.
  const focusRemembered = useCallback(() => {
    const card = element.current?.querySelectorAll('button').item(focused);
    card?.focus({ preventScroll: true });
    if (card) scrollToNearest(card);
  }, [focused, scrollToNearest]);
  const cardFocused = useCallback(
    (index: number, card: HTMLElement): void => {
      setFocused(index);
      // Moving a card under a pressed pointer would send the release elsewhere and lose the click.
      if (card.matches(KEYBOARD_FOCUS)) scrollToNearest(card);
    },
    [scrollToNearest],
  );
  return { viewport, element, focused, focusRemembered, cardFocused };
}

