import { PNG } from 'pngjs';
import { expect, test } from './browser-test.ts';
import { FACE_COUNT } from '../src/game/board/face-design.ts';
import { ART_URL, loadFixedBoard } from './game-fixture.ts';
import type { Page } from '@playwright/test';
import assert from 'node:assert/strict';

test('the face sheet stays a face sheet without a session-harness branch', async ({ page }) => {
  await page.goto(ART_URL + '#session');
  await expect(page.locator('figure')).toHaveCount(128);
  await expect(page.locator('.board-viewport')).toHaveCount(0);
  await expect(page.getByRole('button', { name: 'Unmount game', exact: true })).toHaveCount(0);
});

function silhouette(png: Buffer): string {
  const image = PNG.sync.read(png);
  assert.equal(image.width, 44);
  assert.equal(image.height, 44);
  const pixels: string[] = [];
  for (let offset = 0; offset < image.data.length; offset += 4) {
    const red = image.data[offset];
    const green = image.data[offset + 1];
    const blue = image.data[offset + 2];
    assert.ok(red !== undefined && green !== undefined && blue !== undefined);
    pixels.push(red + green + blue > 128 * 3 ? '1' : '0');
  }
  return pixels.join('');
}

test('the actual 44px faces keep distinct geometry without color cues', async ({
  page,
}, artifacts) => {
  await page.setViewportSize({ width: 1200, height: 900 });
  await page.goto(ART_URL);
  await expect(page.locator('figure .card')).toHaveCount(FACE_COUNT);
  await page.screenshot({ path: artifacts.outputPath('face-sheet-color.png'), fullPage: true });
  await page.addStyleTag({ content: '.face-sheet { filter: grayscale(1); }' });
  await page.screenshot({ path: artifacts.outputPath('face-sheet-grayscale.png'), fullPage: true });
  await page.locator('figure svg').evaluateAll((elements) => {
    for (const element of elements) {
      const shape = element.querySelector('g');
      const marker = element.querySelector(':scope > circle');
      if (!shape || !marker) throw new Error('Missing face geometry.');
      if (shape.getAttribute('fill') !== 'none') shape.setAttribute('fill', '#F4F6FF');
      shape.setAttribute('stroke', '#F4F6FF');
      marker.setAttribute('fill', '#F4F6FF');
    }
  });
  const masks = [];
  for (const card of await page.locator('figure .card').all())
    masks.push(silhouette(await card.screenshot()));
  expect(new Set(masks).size).toBe(FACE_COUNT);
  await page.screenshot({ path: artifacts.outputPath('face-sheet-neutral.png'), fullPage: true });
});

test('the face marker keeps the specified surround and geometry', async ({ page }) => {
  await page.goto(ART_URL);
  const geometry = await page
    .locator('figure svg')
    .first()
    .evaluate((element) => {
      const marker = element.querySelector(':scope > circle');
      const shape = element.querySelector('g');
      if (!marker || !shape) throw new Error('Missing geometry.');
      return {
        viewBox: element.getAttribute('viewBox'),
        radius: marker.getAttribute('r'),
        stroke: marker.getAttribute('stroke-width'),
        background: getComputedStyle(marker).stroke,
      };
    });
  expect(geometry).toEqual({
    viewBox: '0 0 100 100',
    radius: '5',
    stroke: '3',
    background: 'rgb(17, 22, 37)',
  });
});

test('solid fills, outline strokes and marker fills share the face palette color', async ({
  page,
}) => {
  await page.goto(ART_URL);
  const colors = [
    '#63E7FF',
    '#FF71D6',
    '#8BEA7D',
    '#FFE082',
    '#FFB064',
    '#B49AFF',
    '#FF8296',
    '#D9F3FF',
  ];
  const actual = await page.locator('figure svg').evaluateAll((elements) =>
    elements.map((element) => ({
      fill: element.querySelector('g')?.getAttribute('fill'),
      stroke: element.querySelector('g')?.getAttribute('stroke'),
      marker: element.querySelector(':scope > circle')?.getAttribute('fill'),
    })),
  );
  expect(actual).toHaveLength(FACE_COUNT);
  for (const [id, face] of actual.entries()) {
    const color = colors[Math.floor(id / 8) % colors.length];
    expect(face).toEqual({ fill: id < 64 ? color : 'none', stroke: color, marker: color });
  }
});

// Card size, the grid it sits in and the board's custom properties depend on where a card is
// placed. Every other computed style must come from the card's own styles.
const PLACEMENT = new Set([
  'width',
  'height',
  'inline-size',
  'block-size',
  'min-width',
  'min-height',
  'min-inline-size',
  'min-block-size',
  'grid-template-columns',
  'grid-template-rows',
  'perspective-origin',
  'transform-origin',
]);

function revealedCardStyle(page: Page) {
  return page
    .locator('.card.revealed')
    .first()
    .evaluate(
      async (card, placement) => {
        // The hover border fades back over 120ms, so read the settled style.
        await Promise.all(card.getAnimations().map((animation) => animation.finished));
        const style = getComputedStyle(card);
        return Object.fromEntries(
          Array.from(style)
            .filter((name) => !name.startsWith('--') && !placement.includes(name))
            .map((name) => [name, style.getPropertyValue(name)]),
        );
      },
      [...PLACEMENT],
    );
}

test('the face sheet draws the same card as the game outside the control styles', async ({
  page,
}) => {
  await loadFixedBoard(page);
  await page.locator('.card').first().click();
  await page.mouse.move(0, 0);
  const game = await revealedCardStyle(page);
  await page.goto(ART_URL);
  expect(await revealedCardStyle(page), 'A07 card styles stay with the card').toEqual(game);
});
import assert from 'node:assert/strict';
import { before, after, test as nodeTest } from 'node:test';
import { mkdir, readFile, writeFile } from 'node:fs/promises';
import { basename, join } from 'node:path';
import { chromium, expect as playwrightExpect } from '@playwright/test';
import { spawnSync } from 'node:child_process';
import { REFERENCE_ROOT, serveArtifact } from './artifact-server.ts';
import type { Browser, BrowserContext, BrowserContextOptions, Page } from '@playwright/test';

const BROWSER_TEMP = join(REFERENCE_ROOT, '.browser-work');
const RESULTS = join(REFERENCE_ROOT, 'test-results');
const CHROMIUM_VERSION = '156.0.8078.4';
const EXECUTABLE_ENV = 'PLAYWRIGHT_CHROMIUM_EXECUTABLE';
// Set to 1 for named-combination evidence. Other supported runtimes run and record their versions.
const NAMED_COMBINATION_ENV = 'NEON_PAIRS_NAMED_COMBINATION';
const NAMED_COMBINATION = {
  node: '26.12.1',
  npm: '11.20.0',
  playwright: '1.64.1',
  chromium: CHROMIUM_VERSION,
};
// Playwright hides scrollbars by default. Visible ones take layout space, as on a Windows desktop.
const HIDE_SCROLLBARS = '--hide-scrollbars';
export const Scrollbars = { hidden: 'hidden', visible: 'visible' } as const;
type ScrollbarMode = (typeof Scrollbars)[keyof typeof Scrollbars];
// A busy verifier runs many browsers at once, so a single wait gets more than Playwright's 5s default.
export const expect = playwrightExpect.configure({ timeout: 15_000 });
// Most journeys fit the standard limit. The accessibility journey and the large boards take the long one.
export const TestTimeouts = { standard: 30_000, long: 90_000 } as const;
// npm names itself and its version to every script it runs, so a browser file needs no npm process of its own.
const NPM_AGENT_ENV = 'npm_config_user_agent';
let browser: Browser | undefined;
let scrollbarBrowser: Promise<Browser> | undefined;
let artifact: Awaited<ReturnType<typeof serveArtifact>> | undefined;

before(async () => {
  await mkdir(BROWSER_TEMP, { recursive: true });
  await mkdir(RESULTS, { recursive: true });
  process.env.TEMP = BROWSER_TEMP;
  process.env.TMP = BROWSER_TEMP;
  const npm = /^npm\/(\S+)/.exec(process.env[NPM_AGENT_ENV] ?? '')?.[1] ?? npmVersion();
  const playwright: unknown = JSON.parse(
    await readFile(new URL(import.meta.resolve('@playwright/test/package.json')), 'utf8'),
  );
  assert.ok(playwright && typeof playwright === 'object' && 'version' in playwright);
  browser = await launch(Scrollbars.hidden);
  const runtime = {
    node: process.versions.node,
    npm,
    playwright: String(playwright.version),
    chromium: browser.version(),
  };
  const named = process.env[NAMED_COMBINATION_ENV] === '1';
  await writeFile(
    join(RESULTS, 'browser-runtime.json'),
    JSON.stringify({ ...runtime, namedCombination: named }, null, 2),
  );
  if (named) assert.deepEqual(runtime, NAMED_COMBINATION, 'T03 named combination');
  artifact = await serveArtifact();
});

after(async () => {
  await browser?.close();
  await (await scrollbarBrowser)?.close();
  await artifact?.close();
});

function launch(scrollbars: ScrollbarMode): Promise<Browser> {
  const executable = process.env[EXECUTABLE_ENV];
  return chromium.launch({
    headless: true,
    ...(executable ? { executablePath: executable } : {}),
    ...(scrollbars === Scrollbars.visible ? { ignoreDefaultArgs: [HIDE_SCROLLBARS] } : {}),
  });
}

interface BrowserFixture {
  browser: Browser;
  context: BrowserContext;
  page: Page;
  gameURL: string;
}
interface Artifacts {
  outputPath(file: string): string;
}

function npmVersion(): string {
  const npmResult =
    process.platform === 'win32'
      ? spawnSync('cmd.exe', ['/d', '/c', 'npm --version'], { encoding: 'utf8' })
      : spawnSync('npm', ['--version'], { encoding: 'utf8' });
  assert.equal(npmResult.status, 0, 'T03 npm version command');
  return npmResult.stdout.trim();
}

export function test(
  name: string,
  body: (fixture: BrowserFixture, artifacts: Artifacts) => Promise<void>,
  options: BrowserContextOptions = {},
  scrollbars: ScrollbarMode = Scrollbars.hidden,
  timeout: number = TestTimeouts.standard,
): void {
  nodeTest(name, { timeout }, async (t) => {
    if (!browser || !artifact) throw new Error('Browser verification did not start.');
    const owner =
      scrollbars === Scrollbars.visible ? await (scrollbarBrowser ??= launch(scrollbars)) : browser;
    const context = await owner.newContext(options);
    t.after(() => context.close());
    const page = await context.newPage();
    const pageErrors: string[] = [];
    page.on('pageerror', (error) => pageErrors.push(error.message));
    const directory = join(RESULTS, name.replace(/[^a-z0-9]+/gi, '-'));
    await mkdir(directory, { recursive: true });
    const artifacts = {
      outputPath(file: string): string {
        if (basename(file) !== file) throw new Error('Expected an artifact filename.');
        return join(directory, file);
      },
    };
    await body({ browser: owner, context, page, gameURL: artifact.url }, artifacts);
    assert.deepEqual(pageErrors, []);
  });
}
